{
  title: 'Effects/Dynamic Background',
  component: DynamicBackgroundComponent,
  decorators: [
    moduleMetadata({
      imports: [CommonModule, DynamicBackgroundComponent],
    }),
  ],
  tags: ['autodocs'],
  parameters: {
    docs: {
      description: {
        component: `
Un fondo animado en 3D usando **Three.js**.

Este componente renderiza efectos dinámicos (por ejemplo una esfera deformada).  
Puedes personalizar el **efecto**, la **velocidad de rotación**, el **tamaño** y los **colores**.
        `,
      },
    },
    layout: 'fullscreen',
  },
  argTypes: {
    effect: {
      control: { type: 'select' },
      options: ['sphere-deform', 'ring-transform', 'particles'],
      description: 'Efecto visual a renderizar.',
    },
    rotationSpeed: {
      control: { type: 'number', min: 0, max: 0.1, step: 0.01 },
      description: 'Velocidad de rotación del efecto.',
    },
    size: {
      control: { type: 'number', min: 1, max: 10, step: 1 },
      description: 'Tamaño base del objeto 3D.',
    },
    backgroundColor: {
      control: 'color',
      description: 'Color de fondo del canvas.',
    },
    elementColor: {
      control: 'color',
      description: 'Color del objeto renderizado (si aplica).',
    },
  },
}

{
  title: 'Effects/Sphere Deform',
  component: DynamicBackgroundComponent,
  decorators: [
    moduleMetadata({
      imports: [CommonModule, DynamicBackgroundComponent],
    }),
  ],
  tags: ['autodocs'],
  parameters: {
    docs: {
      description: {
        component: `
Efecto **Sphere Deform** para \`<lib-dynamic-background>\`.

Esta variante genera una esfera con pliegues dinámicos que se deforman de forma orgánica en tiempo real.  
Se puede personalizar tamaño, velocidad de rotación y color.`,
      },
    },
    layout: 'fullscreen',
  },
}

{
  parameters: {
    layout: 'fullscreen',
    docs: {
      inlineStories: false, // Forzar iframe en Docs también
    },
    viewport: {
      defaultViewport: 'desktop',
      viewports: {
        mobile: {
          name: 'Mobile (375x667)',
          styles: {
            width: '375px',
            height: '667px',
          },
          type: 'mobile',
        },
        tablet: {
          name: 'Tablet (768x1024)',
          styles: {
            width: '768px',
            height: '1024px',
          },
          type: 'tablet',
        },
        desktop: {
          name: 'Desktop (1440x900)',
          styles: {
            width: '1440px',
            height: '900px',
          },
          type: 'desktop',
        },
      },
    },
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
  },
}

